<?php
namespace App\Services;use App\Models\{ApLoadSample,HeatmapRun,Measurement,SystemThreshold};use Carbon\CarbonInterface;use Illuminate\Database\Eloquent\Builder;
class DashboardMetricsService{
 public function calculate(?int $floorId,CarbonInterface $from,CarbonInterface $to,string $source='all'):array{
  $query=Measurement::query()->whereBetween('captured_at',[$from,$to])->whereHas('point',fn(Builder $q)=>$q->when($floorId,fn($q)=>$q->whereHas('survey',fn($q)=>$q->where('floor_id',$floorId))));
  if($source!=='all')$query->where('source_type',$source);$all=(clone$query)->get();$real=$all->where('is_simulated',false);$rssi=$real->pluck('rssi_dbm')->filter(fn($v)=>$v!==null);$down=$real->pluck('download_mbps')->filter(fn($v)=>$v!==null);$up=$real->pluck('upload_mbps')->filter(fn($v)=>$v!==null);$lat=$real->pluck('latency_ms')->filter(fn($v)=>$v!==null);$loss=$real->pluck('packet_loss_percent')->filter(fn($v)=>$v!==null);
  $heatmap=HeatmapRun::query()->where('status','completed')->when($floorId,fn($q)=>$q->whereHas('survey',fn($q)=>$q->where('floor_id',$floorId)))->where('generated_at','<=',$to)->latest('generated_at')->first();
  $coverage=$heatmap?->coverage_percent!==null?(float)$heatmap->coverage_percent:null;$components=['coverage'=>$coverage,'throughput'=>$this->scoreHigher($this->median($down),SystemThreshold::number('throughput_good_mbps',25)),'latency'=>$this->scoreLower($this->median($lat),SystemThreshold::number('latency_good_ms',50)),'packet_loss'=>$this->scoreLower($this->median($loss),SystemThreshold::number('packet_loss_good_percent',1)),'stability'=>$loss->isNotEmpty()?max(0,100-((float)$loss->avg()*10)):null,'ap_load'=>$this->scoreLower($this->median(ApLoadSample::query()->whereBetween('sampled_at',[$from,$to])->when($floorId,fn($q)=>$q->whereHas('accessPoint',fn($q)=>$q->where('floor_id',$floorId)))->pluck('channel_utilisation_percent')->filter(fn($v)=>$v!==null)),SystemThreshold::number('channel_utilisation_high_percent',70))];$weights=['coverage'=>.30,'throughput'=>.20,'latency'=>.15,'packet_loss'=>.15,'stability'=>.10,'ap_load'=>.10];$score=0;$available=0;foreach($components as $k=>$v)if($v!==null){$score+=$v*$weights[$k];$available+=$weights[$k];}
  return ['counts'=>['total'=>$all->count(),'real'=>$real->count(),'simulated'=>$all->where('is_simulated',true)->count()],'coverage'=>['value'=>$coverage,'threshold_dbm'=>SystemThreshold::number('rssi_weak_dbm',-75),'source_points'=>$heatmap?->source_point_count,'estimated_area_percent'=>$heatmap?->estimated_area_percent,'algorithm'=>$heatmap?->algorithm,'calculated_at'=>$heatmap?->generated_at],'performance'=>['median_rssi_dbm'=>$this->median($rssi),'median_download_mbps'=>$this->median($down),'median_upload_mbps'=>$this->median($up),'median_latency_ms'=>$this->median($lat),'median_packet_loss_percent'=>$this->median($loss)],'health'=>['value'=>$available>0?round($score,1):null,'available_weight_percent'=>round($available*100,1),'complete'=>$available===1.0,'components'=>$components,'weights'=>$weights,'limitation'=>$available<1?'Health score incomplete because one or more components are unavailable. No silent reweighting was applied.':null],'provenance'=>$all->groupBy('source_type')->map->count()->all(),'period'=>['from'=>$from->toIso8601String(),'to'=>$to->toIso8601String()],'calculation_version'=>'1.0'];
 }
 private function median($c):?float{if($c->isEmpty())return null;$s=$c->map(fn($v)=>(float)$v)->sort()->values();$n=$s->count();return round($n%2?$s[intdiv($n,2)]:($s[$n/2-1]+$s[$n/2])/2,3);}private function scoreHigher(?float $v,float $good):?float{return $v===null?null:round(min(100,max(0,($v/$good)*100)),2);}private function scoreLower(?float $v,float $good):?float{return $v===null?null:round(min(100,max(0,100-(max(0,$v-$good)/max($good,1))*50)),2);}}
